import React from 'react';
import { Box, Chip, Stack, Typography, type BoxProps } from '@mui/material';
import { BRAND_LOGO_SRC, BRAND_TAGLINE } from '../constants/brand';
import { BASELINE_SOFTWARE_VERSION } from '../constants/version';

export type BrandLockupVariant = 'full' | 'compact';

export interface BrandLockupProps extends BoxProps {
  /** `full` matches the launch screen logo; `compact` is the logo image for headers and nav. */
  variant?: BrandLockupVariant;
  /** Full variant: image width. Compact variant: max logo height in pixels. */
  logoWidth?: number | string;
  /** Shows Measure · Report · Reduce beside the logo (compact header lockup). */
  showTagline?: boolean;
  /** Shows baseline software version beside the logo (compact header lockup). */
  showVersion?: boolean;
}

const versionChipSx = {
  height: 20,
  '& .MuiChip-label': {
    px: 1,
    fontSize: '0.68rem',
    fontWeight: 700,
    letterSpacing: 0.2,
  },
} as const;

/**
 * Logo lockup aligned with the application launch screen.
 */
const BrandLockup: React.FC<BrandLockupProps> = ({
  variant = 'full',
  logoWidth,
  showTagline = false,
  showVersion = false,
  sx,
  ...rest
}) => {
  if (variant === 'full') {
    const width = logoWidth ?? 'min(520px, 92vw)';

    return (
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          mx: 'auto',
          ...sx,
        }}
        {...rest}
      >
        <Box
          component="img"
          src={BRAND_LOGO_SRC}
          alt="sustainow Carbon Intelligence"
          sx={{
            width,
            height: 'auto',
            maxWidth: '100%',
            display: 'block',
          }}
        />
      </Box>
    );
  }

  const logoHeight = typeof logoWidth === 'number' ? logoWidth : 48;

  return (
    <Box
      sx={{
        display: 'flex',
        alignItems: 'center',
        gap: 1.25,
        minWidth: 0,
        ...sx,
      }}
      {...rest}
    >
      <Box
        component="img"
        src={BRAND_LOGO_SRC}
        alt="sustainow Carbon Intelligence"
        sx={{
          height: logoHeight,
          width: 'auto',
          maxWidth: { xs: 180, sm: 220 },
          flexShrink: 0,
          objectFit: 'contain',
          display: 'block',
        }}
      />
      {(showTagline || showVersion) && (
        <Stack
          spacing={0.25}
          sx={{
            minWidth: 0,
            display: { xs: 'none', sm: 'flex' },
          }}
        >
          {showTagline && (
            <Typography
              variant="caption"
              sx={{
                color: 'text.secondary',
                fontWeight: 500,
                lineHeight: 1.2,
              }}
            >
              {BRAND_TAGLINE}
            </Typography>
          )}
          {showVersion && (
            <Chip
              size="small"
              label={`Version ${BASELINE_SOFTWARE_VERSION}`}
              sx={versionChipSx}
              variant="outlined"
              color="default"
            />
          )}
        </Stack>
      )}
    </Box>
  );
};

export default BrandLockup;
