import React, { useEffect, Suspense } from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Container, Box } from '@mui/material';
import Header from './components/Header';
import AppSidebar from './components/AppSidebar';
import { shouldShowAppSidebar } from './constants/appNavigation';
import { useRegistration } from './context/RegistrationContext';
import ErrorBoundary from './components/ErrorBoundary';
import MSMERegistration from './components/MSMERegistration';
import PreLoginDashboard from './components/PreLoginDashboard';
import PricingPage from './components/PricingPage';
import Dashboard from './components/Dashboard';
import CarbonSavings from './components/CarbonSavings';
import ComplianceHubHome from './components/compliance/ComplianceHubHome';
import IndiaComplianceTrack from './components/compliance/IndiaComplianceTrack';
import ExportComplianceTrack from './components/compliance/ExportComplianceTrack';
import GreenLoans from './components/GreenLoans';
import EmissionsReductionTargets from './components/EmissionsReductionTargets';
import DocumentUpload from './components/DocumentUpload';
import DataPrivacy from './components/DataPrivacy';
import BillingPage from './components/BillingPage';
import CarbonTrading from './components/CarbonTrading';
import GIFTSchemes from './components/GIFTSchemes';
import GIFTApplications from './components/GIFTApplications';
import GIFTApplicationForm from './components/GIFTApplicationForm';
import ProtectedRoute from './components/ProtectedRoute';
import RequireMSME from './components/RequireMSME';
import RequireWorkflowPlanner from './components/RequireWorkflowPlanner';
import UserLogin from './components/UserLogin';
import EnterpriseRoutesRedirect from './components/EnterpriseRoutesRedirect';
import { RegistrationProvider } from './context/RegistrationContext';
import { OrganizationProvider } from './context/OrganizationContext';
import UserRegister from './components/UserRegister';
import ForgotPassword from './components/ForgotPassword';
import ResetPassword from './components/ResetPassword';
import MSMEProfileSection from './components/MSMEProfileSection';
import InformationPage from './components/InformationPage';
import {
  HelpCenterPage,
  PrivacyPolicyPage,
  SettingsPage,
  TermsOfServicePage,
} from './components/StaticPages';
import AdminLogin from './components/admin/AdminLogin';
import AdminDashboard from './components/admin/AdminDashboard';
import MSMEDetailView from './components/admin/MSMEDetailView';
import AdminRoute from './components/admin/AdminRoute';
import NotFoundPage from './components/NotFoundPage';
import NavigationRouteProgress from './components/NavigationRouteProgress';
import RouteLoadingGate from './components/RouteLoadingGate';
import UpgradePromptBanner from './components/UpgradePromptBanner';
import { APP_CONTENT_GUTTER } from './constants/appShellLayout';
import { resolveDocumentTitle } from './utils/routePageMeta';

const CarbonForecastingGraph = React.lazy(() => import('./components/CarbonForecastingGraph'));
const CarbonFootprint = React.lazy(() => import('./components/CarbonFootprint'));
const CarbonAnalyticsPage = React.lazy(() => import('./components/CarbonAnalyticsPage'));
const ReportingScreen = React.lazy(() => import('./components/ReportingScreen'));
const DataConnectorsPage = React.lazy(() => import('./components/DataConnectorsPage'));
const OperationsPage = React.lazy(() => import('./components/OperationsPage'));

interface RouteWrapperProps {
  children: React.ReactElement;
}

const OnboardedRoute: React.FC<RouteWrapperProps> = ({ children }) => (
  <ProtectedRoute>
    <RequireMSME>
      <RequireWorkflowPlanner>{children}</RequireWorkflowPlanner>
    </RequireMSME>
  </ProtectedRoute>
);

const RequireMSMEProfile: React.FC<RouteWrapperProps> = ({ children }) => (
  <ProtectedRoute>
    <RequireMSME>{children}</RequireMSME>
  </ProtectedRoute>
);

function AppRoutes() {
  const location = useLocation();
  const { isRegistered } = useRegistration();
  const showSidebar = shouldShowAppSidebar(location.pathname, isRegistered);

  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
  }, [location.pathname, location.search]);

  useEffect(() => {
    document.title = resolveDocumentTitle(location.pathname || '/');
  }, [location.pathname]);

  return (
    <Box
      sx={{
        flexGrow: 1,
        minHeight: '100vh',
        backgroundColor: 'background.default',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      <NavigationRouteProgress />
      <Header />

      <Box sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}>
        {showSidebar && <AppSidebar />}

        <Container
          disableGutters
          sx={{
            px: APP_CONTENT_GUTTER,
            pt: { xs: 2.5, md: 3 },
            pb: { xs: 2.5, md: 4 },
            maxWidth: { lg: 1280, xl: 1400 },
            flex: 1,
            minWidth: 0,
            minHeight: 0,
            overflowY: 'auto',
          }}
        >
          <Box
            id="main-content"
            component="main"
            sx={{
              pb: { xs: 2, md: 3 },
            }}
          >
              {showSidebar && isRegistered ? <UpgradePromptBanner /> : null}
              <Suspense fallback={<RouteLoadingGate message="Loading page..." minHeight="40vh" />}>
              <Routes>
              <Route
                path="/msme-registration"
                element={(
                  <ProtectedRoute>
                    <MSMERegistration />
                  </ProtectedRoute>
                )}
              />
              <Route path="/" element={<PreLoginDashboard />} />
              <Route path="/pricing" element={<PricingPage />} />
              <Route path="/login" element={<UserLogin />} />
              <Route path="/register" element={<UserRegister />} />
              <Route path="/enterprise/*" element={<EnterpriseRoutesRedirect />} />
              <Route path="/forgot-password" element={<ForgotPassword />} />
              <Route path="/reset-password" element={<ResetPassword />} />
              <Route path="/privacy-policy" element={<PrivacyPolicyPage />} />
              <Route path="/terms-of-service" element={<TermsOfServicePage />} />
              <Route path="/help" element={<HelpCenterPage />} />
              <Route path="/admin" element={<Navigate to="/admin/login" replace />} />
              <Route path="/admin/login" element={<AdminLogin />} />
              <Route
                path="/admin/dashboard"
                element={(
                  <AdminRoute>
                    <AdminDashboard />
                  </AdminRoute>
                )}
              />
              <Route
                path="/admin/msme/:id"
                element={(
                  <AdminRoute>
                    <MSMEDetailView />
                  </AdminRoute>
                )}
              />
              <Route
                path="/dashboard"
                element={(
                  <OnboardedRoute>
                    <Dashboard />
                  </OnboardedRoute>
                )}
              />
              <Route path="/msme-list" element={<Navigate to="/dashboard" replace />} />
              <Route
                path="/msme-profile"
                element={(
                  <RequireMSMEProfile>
                    <MSMEProfileSection />
                  </RequireMSMEProfile>
                )}
              />
              <Route
                path="/msme-profile/workflow-planner"
                element={<Navigate to="/operations" replace />}
              />
              <Route
                path="/operations"
                element={(
                  <OnboardedRoute>
                    <OperationsPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-footprint"
                element={(
                  <OnboardedRoute>
                    <CarbonFootprint />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-analytics"
                element={(
                  <OnboardedRoute>
                    <CarbonAnalyticsPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-marketplace"
                element={(
                  <OnboardedRoute>
                    <CarbonTrading />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-credits"
                element={(
                  <Navigate to="/carbon-marketplace" replace />
                )}
              />
              <Route
                path="/carbon-trading"
                element={(
                  <Navigate to="/carbon-marketplace" replace />
                )}
              />
              <Route
                path="/carbon-savings"
                element={(
                  <OnboardedRoute>
                    <CarbonSavings />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-schemes"
                element={(
                  <OnboardedRoute>
                    <GIFTSchemes />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications"
                element={(
                  <OnboardedRoute>
                    <GIFTApplications />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications/new"
                element={(
                  <OnboardedRoute>
                    <GIFTApplicationForm />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications/:schemeId/new"
                element={(
                  <OnboardedRoute>
                    <GIFTApplicationForm />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/gift-applications/:id/edit"
                element={(
                  <OnboardedRoute>
                    <GIFTApplicationForm />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/recommendations"
                element={<Navigate to="/emissions-reduction-targets?tab=2" replace />}
              />
              <Route path="/incentives" element={<Navigate to="/gift-schemes" replace />} />
              <Route
                path="/compliance"
                element={(
                  <OnboardedRoute>
                    <ComplianceHubHome />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/compliance/india"
                element={(
                  <OnboardedRoute>
                    <IndiaComplianceTrack />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/compliance/export"
                element={(
                  <OnboardedRoute>
                    <ExportComplianceTrack />
                  </OnboardedRoute>
                )}
              />
              <Route path="/reports" element={<Navigate to="/reporting" replace />} />
              <Route
                path="/reporting"
                element={(
                  <OnboardedRoute>
                    <ReportingScreen />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/green-loans"
                element={(
                  <OnboardedRoute>
                    <GreenLoans />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/carbon-forecasting"
                element={(
                  <OnboardedRoute>
                    <CarbonForecastingGraph />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/emissions-reduction-targets"
                element={(
                  <OnboardedRoute>
                    <EmissionsReductionTargets />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/document-upload"
                element={(
                  <OnboardedRoute>
                    <DocumentUpload />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/data"
                element={(
                  <OnboardedRoute>
                    <DataConnectorsPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/document-management"
                element={(
                  <Navigate to="/document-upload" replace />
                )}
              />
              <Route
                path="/data-privacy"
                element={(
                  <OnboardedRoute>
                    <DataPrivacy />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/billing"
                element={(
                  <OnboardedRoute>
                    <BillingPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/manufacturing-workflow"
                element={(
                  <Navigate to="/operations" replace />
                )}
              />
              <Route
                path="/settings"
                element={(
                  <OnboardedRoute>
                    <SettingsPage />
                  </OnboardedRoute>
                )}
              />
              <Route
                path="/information"
                element={(
                  <OnboardedRoute>
                    <InformationPage />
                  </OnboardedRoute>
                )}
              />
                <Route path="*" element={<NotFoundPage />} />
              </Routes>
              </Suspense>
          </Box>
        </Container>
      </Box>
    </Box>
  );
}

function App() {
  return (
    <RegistrationProvider>
      <OrganizationProvider>
        <ErrorBoundary>
          <AppRoutes />
        </ErrorBoundary>
      </OrganizationProvider>
    </RegistrationProvider>
  );
}

export default App;
